import{_ as e,c as t,o as r,ae as n}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse('{"title":"REFORMING ACCREDITATION TO STRENGTHEN HIGHER EDUCATION","description":"","frontmatter":{"title":"REFORMING ACCREDITATION TO STRENGTHEN HIGHER EDUCATION","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/reforming-accreditation-to-strengthen-higher-education/","publishDate":"2025-04-23T18:21:34-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-23-reforming-accreditation-to-strengthen-higher-education.md","filePath":"executive-orders/2025-04-23-reforming-accreditation-to-strengthen-higher-education.md"}'),o={name:"executive-orders/2025-04-23-reforming-accreditation-to-strengthen-higher-education.md"};function a(s,i,l,c,d,u){return r(),t("div",null,i[0]||(i[0]=[n('<h1 id="reforming-accreditation-to-strengthen-higher-education" tabindex="-1">REFORMING ACCREDITATION TO STRENGTHEN HIGHER EDUCATION <a class="header-anchor" href="#reforming-accreditation-to-strengthen-higher-education" aria-label="Permalink to &quot;REFORMING ACCREDITATION TO STRENGTHEN HIGHER EDUCATION&quot;">​</a></h1><p>Published: Wednesday, April 23, 2025</p><ul><li><p><strong>Purpose of the Executive Order:</strong></p><ul><li>Address issues with higher education accreditors&#39; performance in ensuring quality education for colleges and universities.</li><li>Recognize the accreditors&#39; failure to prioritize student outcomes and their tendency to impose discriminatory practices under the guise of “diversity, equity, and inclusion” (DEI) standards.</li></ul></li><li><p><strong>Concerns Raised:</strong></p><ul><li>Accreditors have endorsed low-quality institutions despite low graduation rates (64% in 2020) and poor return on investment for students.</li><li>Some accredited programs contribute to significant student debt without adequate earning potential for graduates.</li><li>Accreditors focus on promoting DEI standards that may lead to unlawful discrimination, interfering with local governance.</li></ul></li><li><p><strong>Specific Examples of Discriminatory Standards:</strong></p><ul><li><strong>American Bar Association (ABA):</strong> Requires law schools to demonstrate commitment to diversity, violating Supreme Court rulings.</li><li><strong>Liaison Committee on Medical Education:</strong> Mandates diversity in student recruitment, diverting focus from quality medical education.</li></ul></li><li><p><strong>Actions Ordered:</strong></p><ul><li><strong>Accountability Measures:</strong><ul><li>Secretary of Education to hold accreditors accountable for failing to meet federal recognition criteria or for requiring unlawful discrimination.</li><li>Attorney General and Secretary of Education to investigate and act against discriminatory accreditation requirements.</li></ul></li></ul></li><li><p><strong>Reforms to Accreditation:</strong></p><ul><li>Ensure accreditation focuses on high-quality education and does not involve unlawful discrimination.</li><li>Facilitate intellectual diversity, reduce barriers to new educational models, and prevent unnecessary credential inflation.</li><li>Resume recognizing new accreditors for increased competition and accountability, ensuring use of program-level student outcomes data without bias.</li></ul></li><li><p><strong>Implementation:</strong></p><ul><li>Consistent application of the order within legal frameworks and availability of resources.</li><li>Emphasize transparency and efficiency in the accreditation process while allowing institutions flexibility in changing accreditors.</li></ul></li><li><p><strong>Clarifications:</strong></p><ul><li>The order does not impair existing legal authority or create enforceable rights against the United States or its entities.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/reforming-accreditation-to-strengthen-higher-education/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/reforming-accreditation-to-strengthen-higher-education/</a></p>',4)]))}const p=e(o,[["render",a]]);export{h as __pageData,p as default};
